-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"شرح بيتين وفق دليل لغوي","passage":"لا يجوز اختلاق بيتين للمتنبي بغرض شرح مقرر «شرح بيتين للمتنبي». المثال النثري المستقل: «يسعى الإنسان إلى المعالي بالصبر والعمل». يبدأ الشرح بتحديد الكلمات والدلالة والصورة والعلاقة بالسياق، ثم يعود إلى النص الموثق لا إلى المثال.","prompt":"ما أول شرط لتحليل بيتين منسوبين للمتنبي؟","correct":"الحصول على نص البيتين الصحيح","w1":"اختراع قافية مناسبة","w2":"حذف الألفاظ الصعبة","w3":"الاكتفاء بعنوان الدرس","practice":"احصل على البيتين من الكتاب المقرر، وفسر ألفاظهما وصورة بلاغية فيهما مع شاهد دقيق."},{"n":2,"skill":"دلالة المركب من مجموع أجزائه","passage":"في «بيت العلم» يدل المركب الإضافي على منشأة تُنسب إلى العلم، بينما «بيتٌ واسع» مركب وصفي يذكر صفة البيت، و«على الطريق» جار ومجرور يتعلق بحسب السياق. لا تكفي معرفة معنى الكلمة وحدها لفهم العلاقة النحوية والدلالية.","prompt":"ما نوع المركب «بيت العلم»؟","correct":"مركب إضافي","w1":"جملة فعلية","w2":"مركب وصفي فقط","w3":"أسلوب شرط","practice":"حلل خمسة مركبات إضافية وخمسة وصفية في جمل وفسر أثر التركيب في الدلالة."},{"n":3,"skill":"معاني حروف الجر في السياق","passage":"في «خرجت من المكتبة» «من» لابتداء الغاية المكانية، وفي «ذهبت إلى المدرسة» «إلى» لانتهاء الغاية، وفي «كتبت بالقلم» الباء للاستعانة بالأداة. تتعدد دلالات الحروف بحسب التركيب، فلا يلزم معنى واحد لكل حرف.","prompt":"أي حرف يفيد انتهاء الغاية في المثال؟","correct":"إلى","w1":"من","w2":"الباء","w3":"عن","practice":"اكتب ثماني جمل توظف من وإلى وعن وعلى وفي والباء والكاف واللام، وحدد المعنى من السياق."},{"n":4,"skill":"مقال الشرح والتحليل","passage":"تحتاج المقالة التي تشرح نصًا قصيرًا إلى تمهيد يحدد الفكرة، ثم تحليل مفردات وصور وعلاقات، ثم رأي مدعوم بشاهد وخاتمة. لا تملأ الصفحات بنقل النص دون تفسير، ولا تنسب عبارة إلى مؤلف دون مصدر.","prompt":"ما الذي يميز التحليل عن إعادة السرد؟","correct":"تفسير الألفاظ والصور مع دليل","w1":"نسخ النص كاملًا","w2":"إلغاء الشاهد","w3":"إطالة المقدمة","practice":"اكتب مخطط مقال يشرح نصًا مأذون الاستخدام، ثم حرر فقرتين تحليليتين مع اقتباس قصير موثق."},{"n":5,"skill":"نقد ادعاء الحداثة بتوازن","passage":"نص «حديث في الحداثة» المنسوب إلى قمر الكيلاني يحتاج القراءة الأصلية قبل تقرير موقفها. نموذج مستقل: رأى متحدث أن كل جديد أفضل، فردت زميلته بأن الفائدة ينبغي اختبارها في أثرها وتكلفتها وسلامتها. لا ينسب الحوار إلى الكاتبة.","prompt":"ما المعيار الذي اقترحته الزميلة؟","correct":"قياس الأثر والتكلفة والسلامة","w1":"الاعتماد على حداثة الشيء فقط","w2":"رفض كل تطوير","w3":"حذف النقاش","practice":"بعد توثيق أطروحة المقال الأصلي، اكتب تعليقًا صحفيًا يذكر حجة مؤيدة وتحفظًا محددًا."},{"n":6,"skill":"التعقيب على قضية القراءة","passage":"العنوان «جودة الأدب ومصير المطالعة» لا يكفي لمعرفة رأي كاتبه. في تدريب مستقل قال طالب إن جودة الكتاب تُقاس بقدرته على إثارة التفكير ووضوح بنائه، فرد آخر بأن اهتمامات القراء مختلفة، واتفقا على مراجعة أمثلة محددة.","prompt":"ما الحل الذي توصل إليه الطالبان؟","correct":"مراجعة أمثلة محددة من الكتب","w1":"منع الاختلاف","w2":"اعتبار كل الكتب متطابقة","w3":"إلغاء القراءة","practice":"اكتب تعقيبًا من فقرتين على مقال موثق عن القراءة يتضمن موقف الكاتب وردك بدليل."},{"n":7,"skill":"مطابقة العدد للمعدود","passage":"«ثلاثةُ كتبٍ» يأتي العدد من ثلاثة إلى عشرة مخالفًا للمعدود في التذكير والتأنيث، ومعدوده جمع مجرور بالإضافة في هذا المثال. «ثلاثُ صفحاتٍ» مثال للمعدود المؤنث. تختلف أحكام العدد المركب والمعطوف فلا تعمم قاعدة واحدة على الجميع.","prompt":"أي تركيب صحيح عند ذكر ثلاثة كتب؟","correct":"ثلاثة كتب","w1":"ثلاث كتب","w2":"ثالث كتب","w3":"ثلاثة كتابٍ","practice":"اكتب أعدادًا من واحد إلى عشرين مع معدود مذكر ومؤنث، ثم راجع المطابقة والتمييز."},{"n":8,"skill":"العربية والفكر والعلم في تعقيب نقدي","passage":"لا ننسب رأيًا محددًا لأدونيس في نص «اللغة العربية والفكر والعلم» إلا من المصدر الأصلي. تدريب مستقل: عرضت متعلمة تعريفًا عربيًا لمصطلح علمي، ثم أوضحت أصله الأجنبي عند الحاجة لتجنب الغموض. يعالج المثال دقة الشرح ولا يمثل موقف الكاتب.","prompt":"ما الهدف من توضيح أصل المصطلح عند الحاجة؟","correct":"تقليل الغموض وتدقيق المعنى","w1":"منع الفهم","w2":"إلغاء المراجع","w3":"استخدام كلمة غير محددة","practice":"استخرج أطروحة موثقة من النص، ثم اكتب تعقيبًا يناقش قابلية العربية للتعبير العلمي بأمثلة متحققة."},{"n":9,"skill":"التعليق الصحفي بين الخبر والرأي","passage":"الخبر الجيد يحدد ما حدث ومتى ومصدر المعلومة، بينما التعليق يوضح موقف الكاتب وحجته. مثال تدريبي افتراضي: «أعلنت مدرسة إنشاء ركن للقراءة»؛ يجب ألا نخترع تاريخ الإعلان أو حجم التمويل ثم نقدمه كحقيقة.","prompt":"أي عنصر يخص التعليق أكثر من الخبر المجرد؟","correct":"رأي الكاتب المعلل","w1":"عنوان المدرسة","w2":"وقت النشر","w3":"اسم الجهة","practice":"اكتب تعليقًا على خبر افتراضي موسوم بأنه تدريب، مع فصل المعلومة عن الرأي والدليل."},{"n":10,"skill":"معنى الأفعال الناسخة وأثرها","passage":"«كان الجوُّ هادئًا» تتضمن «كان» فعلًا ناسخًا يرفع اسمه وينصب خبره، وقد يدل على الزمن الماضي بحسب السياق. و«أصبح المتعلمُ نشيطًا» تحمل دلالة التحول أو الدخول في الصباح وفق المقصود، مع بقاء أحكام الاسم والخبر.","prompt":"ما إعراب «هادئًا» في «كان الجو هادئًا»؟","correct":"خبر كان منصوب","w1":"اسم كان مرفوع","w2":"فاعل","w3":"مفعول به","practice":"اكتب أربع جمل بأفعال ناسخة مختلفة وأعرب اسم كل فعل وخبره وفسر دلالته."},{"n":11,"skill":"الحروف الناسخة في الجملة الاسمية","passage":"«إنَّ القراءةَ نافعةٌ» تدخل «إنّ» فتنصب الاسم وترفع الخبر، وتفيد التوكيد غالبًا. «لعلَّ النجاحَ قريبٌ» من أخواتها وقد تفيد الترجي. لا تخلط الحروف الناسخة بكان وأخواتها، فعملهما في الاسم والخبر مختلف.","prompt":"ما إعراب «القراءةَ» بعد «إنَّ»؟","correct":"اسم إن منصوب","w1":"خبر إن مرفوع","w2":"فاعل","w3":"مضاف إليه","practice":"كوّن ست جمل بالحروف الناسخة، واضبط الاسم والخبر وفسر المعنى البلاغي."},{"n":12,"skill":"علامات الممنوع من الصرف","passage":"في «مررتُ بأحمدَ» يُجر العلم الممنوع من الصرف بالفتحة نيابةً عن الكسرة إذا لم يُضف ولم تُدخل عليه أل، لكن ليس كل اسم علم ممنوعًا من الصرف. ويتغير الحكم عند الإضافة أو دخول أل في مواضعها.","prompt":"ما علامة الجر في «مررت بأحمدَ»؟","correct":"الفتحة نيابة عن الكسرة","w1":"الضمة","w2":"الألف","w3":"السكون","practice":"أنشئ ثماني جمل لأسماء ممنوعة من الصرف وأسماء مصروفة، مع بيان سبب المنع وعلامة الجر."},{"n":13,"skill":"قراءة السيرة الذاتية الأدبية بمصدر صحيح","passage":"يتطلب مقرر «الأيام» لطه حسين — الجزء الأول الرجوع إلى الأثر الأصلي لا إلى تلخيص غير موثق. مثال مستقل: «تذكر الراوي طريقه إلى المدرسة القديمة وكيف كان يعتمد على الأصوات لمعرفة اقترابه». يوضح دور الذاكرة في السيرة ولا يمثل فصلًا من «الأيام».","prompt":"ما التقنية السردية في المثال؟","correct":"استرجاع ذكرى من الماضي","w1":"حوار مباشر فقط","w2":"تقرير إحصائي","w3":"مسرحية هزلية","practice":"اقرأ مقطعًا من الكتاب الأصلي، واستخرج علامة للسرد الاسترجاعي وشاهدًا على منظور الراوي مع توثيق الصفحة."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=12
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='31c82c79-72de-4e4b-a5dc-6f9e598b3533'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 302 — النص على النص' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G12_T2_ARAB302_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_UNIFIED_G12_T2_ARAB302_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G12_T2_ARAB302_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_UNIFIED_G12_T2_ARAB302_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;